import {BannerNudgeCard, type BannerNudgeCardProps} from './BannerNudgeCard'

export interface BannerNudgeCardPartialProps extends Omit<BannerNudgeCardProps, 'title' | 'icon'> {
  title?: string
  iconPath: string
}

// The icon is decorative: BannerNudgeCard wraps it in an aria-hidden container, so
// alt text would never reach assistive tech. We intentionally do not expose an
// iconAlt prop and render the img with empty alt to keep callers from making
// incorrect accessibility assumptions.
export function BannerNudgeCardPartial({title, iconPath, ...rest}: BannerNudgeCardPartialProps) {
  if (!title) {
    return null
  }

  return <BannerNudgeCard title={title} icon={<img src={iconPath} alt="" width={32} height={32} />} {...rest} />
}
